<script setup lang="ts">
import StatCard from '@/components/StatCard.vue'
import PageHeader from '@/components/PageHeader.vue'
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import client from '@/api/client'
import {useAuthStore} from '@/stores/auth'
import {money,settlementStatus,withdrawalStatus,type ProviderWallet} from '../../../../packages/wallet/contracts'
const metrics: [string, keyof ProviderWallet['summary']][] = [['待确认结算','pendingCents'],['已确认结算','confirmedCents'],['账面已结算','recordedPaidCents']]
const mode=ref('accounting_only'),payout=ref<number|null>(null),paying=ref(false)
const auth=useAuthStore(),page=ref(1),tab=ref('settlements'),data=ref<ProviderWallet|null>(null),error=ref(''),loading=ref(false)
let generation=0
async function load(){const seq=++generation;data.value=null;error.value='';loading.value=true;try{const result=await client.get<ProviderWallet>('/finance/wallet/temple',{params:{page:page.value,mode:mode.value}});if(seq===generation)data.value=result}catch(e){if(seq===generation)error.value=e instanceof Error?e.message:'钱包暂时无法读取'}finally{if(seq===generation)loading.value=false}}
watch([page,mode,()=>auth.token],load,{immediate:true});onBeforeUnmount(()=>generation++)
const total=computed(()=>data.value?(tab.value==='settlements'?data.value.total:data.value.withdrawalTotal):0)
function changeTab(){page.value=1}
async function simulate(id:number){if(paying.value)return;paying.value=true;try{await client.post('/finance/wallet/temple/simulate-payout',{settlementId:id});payout.value=null;await load()}catch(e){error.value=e instanceof Error?e.message:'模拟提现失败'}finally{paying.value=false}}
</script>
<template><div class="df-page temple-wallet"><PageHeader :title='$t("结算记录")' :subtitle='$t("每一笔结算，都有来处")' /><el-alert :title='$t("仅统计本寺院结算份额，不包含大师个人收入。当前为账面记录，含演示业务；真实提现暂未开放，结算状态不代表银行到账。")' type="info" :closable="false" show-icon/>
<el-radio-group v-model="mode" @change="page=1;payout=null"><el-radio-button value="accounting_only">{{ $t("原有账面记录") }}</el-radio-button><el-radio-button value="demo">{{ $t("模拟余额结算") }}</el-radio-button></el-radio-group><p v-if="mode==='demo'">{{ $t("仅展示测试余额订单的寺院份额，模拟提现不会发生真实转账。") }}</p>
<div class="wallet-overview"><StatCard v-for="[label,key] in metrics" :key="key" :label="$t(label)" :value="data?money(data.summary[key]):'—'" /></div>
<el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane :label='$t("结算明细")' name="settlements"/><el-tab-pane :label='$t("历史提现")' name="withdrawals"/></el-tabs>
<div v-if="error" role="alert"><p>{{$t(error)}}</p><el-button @click="load">{{ $t("重新加载") }}</el-button></div><p v-else-if="loading" role="status">{{ $t("正在读取钱包…") }}</p><template v-else-if="data">
<template v-if="tab==='settlements'"><div class="wallet-records"><details v-for="row in data.settlements" :key="row.id"><summary><span><b>{{$t((settlementStatus[row.status] || row.status))}}</b><small>{{$t(row.createdAt)}}</small></span><strong>{{$t(money(row.netCents))}} <small>{{ $t("应结金额 · 详情") }}</small></strong></summary><div v-if="auth.roles.includes('temple_admin')&&mode==='demo'&&data.withdrawEnabled&&row.status!=='paid'"><template v-if="payout===row.id"><p>{{ $t("确认模拟提现 ") }}{{$t(money(row.netCents))}}{{ $t("？不会发生真实转账。") }}</p><el-button :loading="paying" @click="simulate(row.id)">{{ $t("确认模拟提现") }}</el-button><el-button :disabled="paying" @click="payout=null" data-quiet-action="cancel">{{ $t("取消") }}</el-button></template><el-button v-else @click="payout=row.id">{{ $t("模拟提现") }}</el-button></div><dl><dt>{{ $t("结算编号") }}</dt><dd>{{$t(row.number)}}</dd><dt>{{ $t("寺院分配金额") }}</dt><dd>{{$t(money(row.grossCents))}}</dd><dt>{{ $t("平台费用") }}</dt><dd>{{$t(money(row.commissionCents))}}</dd><dt>{{ $t("来源单号") }}</dt><dd>{{$t((row.sourceNo || $t('历史汇总结算')))}}</dd></dl><router-link v-if="auth.can('temple.bookings.read')&&row.sourceType==='booking'&&row.sourceNo" :to="'/bookings/'+encodeURIComponent(row.sourceNo)">{{ $t("查看预约 →") }}</router-link></details></div></template>
<template v-else><p>{{ $t("历史模拟提现仅供核对流程，不代表银行打款成功。") }}</p><div class="wallet-records"><details v-for="row in data.withdrawals" :key="row.id"><summary><span><b>{{$t((withdrawalStatus[row.status] || row.status))}}</b><small>{{$t(row.createdAt)}}</small></span><strong>{{$t(money(row.amountCents))}}</strong></summary><p>{{$t(row.number)}}{{ $t(" · 模拟记录") }}</p></details></div></template>
<el-empty v-if="!total" :description='$t("暂无记录，后续结算会集中展示在这里")'/><el-pagination v-if="total>20||page>1" v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next"/></template></div></template>
<style scoped>.temple-wallet > .el-alert{margin-bottom:var(--admin-section-gap)}.wallet-overview{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.wallet-records details{padding:18px;margin-bottom:12px;border:1px solid var(--el-border-color);border-radius:12px;background:var(--el-bg-color)}summary{cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:16px;min-height:44px}summary small{display:block;font-size:12px;color:var(--el-text-color-secondary);margin-top:6px}summary strong{text-align:right;font-variant-numeric:tabular-nums}dl{display:grid;grid-template-columns:120px 1fr;gap:12px;margin-top:20px}dd{margin:0;overflow-wrap:anywhere}dt{color:var(--el-text-color-secondary)}@media(max-width:700px){.wallet-overview{grid-template-columns:1fr;gap:8px}}
</style>
